// ===== n8n Code node — "Run Once for All Items" =====
// Chunker for PROSE lesson-notes documents (history summary).
// Different shape from the geography doc: no tables, but "---" is a PAGE break
// that cuts through the middle of lessons, so it must NOT be a chunk boundary.

const MAX_CHARS = 1800;
const MIN_CHARS = 50;
const SUBJECT = "تاريخ - لبنان والمشرق العربي";   // change per document

// ---------- cleanup ----------
function normalise(text) {
  return text
    .replace(/CamScanner/gi, '')
    // page separators are NOT topic boundaries in this document — drop them
    .replace(/\n-{3,}\n/g, '\n\n')
    // this author writes some headings as **bold** instead of markdown headings —
    // promote a whole-line bold to a real heading so lessons and sections are both found
    .replace(/^[ \t]*\*\*\s*(.+?)\s*\*\*[ \t]*$/gm, '### $1')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// ---------- lesson detection ----------
// Lesson headers appear with and without markdown "#", and with ١٢٣ or 123 numerals.
const LESSON_RE = /^\s*#{0,4}\s*(الدرس\s+[^\n]{0,80}?)\s*$/m;
const LESSON_RE_G = new RegExp(LESSON_RE.source, 'gm');

function splitIntoLessons(text) {
  const marks = [...text.matchAll(LESSON_RE_G)];
  if (!marks.length) return [{ lesson: '', body: text }];

  const out = [];
  if (marks[0].index > 0) {
    const pre = text.slice(0, marks[0].index).trim();
    if (pre) out.push({ lesson: '', body: pre });     // front matter
  }
  marks.forEach((m, i) => {
    const start = m.index + m[0].length;
    const end = i + 1 < marks.length ? marks[i + 1].index : text.length;
    out.push({ lesson: m[1].trim().replace(/\s*:\s*$/, ''), body: text.slice(start, end).trim() });
  });
  return out;
}

// ---------- section detection inside a lesson ----------
// Two kinds of sub-heading: real markdown "## / ###", and a bare line ending in ":"
// (this document uses both, inconsistently).
function isBareHeading(line) {
  const t = line.trim();
  if (!t || t.length > 70) return false;
  if (/^[-*+]\s/.test(t)) return false;             // bullet
  if (/^\d+[)._-]\s/.test(t)) return false;         // numbered item
  if (/^[\u0621-\u064A][)-]\s/.test(t)) return false; // lettered item
  if (/[:\uFF1A]\s*$/.test(t)) return true;         // ends with a colon
  // a short standalone label with no sentence punctuation is a heading in this
  // document (اجتماعيا / دينيا / اقتصادياً / للعرب / نتائجها / بنودها ...)
  return t.length <= 35 && !/[.\u060C\u061B!?]\s*$/.test(t);
}

function splitIntoSections(body) {
  const lines = body.split('\n');
  const sections = [];
  let current = { heading: '', lines: [] };

  lines.forEach(line => {
    const md = line.match(/^\s*#{1,4}\s*(.+?)\s*$/);   // include h1 — this doc uses it mid-lesson
    if (md || isBareHeading(line)) {
      // push even when the section has no body — a heading-only section is real
      // context (a parent heading) and must not be dropped here
      if (current.heading || current.lines.join('').trim()) sections.push(current);
      const raw = md ? md[1] : line.trim();
      current = { heading: raw.replace(/^#+\s*/, '').replace(/\s*:\s*$/, ''), lines: [] };
    } else {
      current.lines.push(line);
    }
  });
  if (current.lines.join('').trim() || current.heading) sections.push(current);

  const flat = sections.map(s => ({ heading: s.heading, text: s.lines.join('\n').trim() }));
  const out = [];
  let parents = [];
  flat.forEach(s => {
    // a heading with no body of its own is context for what follows. Several can
    // stack up (مراحل عهد الإنتداب / دام الإنتداب / فرنسي مباشر / عسكري) — keep the
    // whole chain, otherwise every one but the last is silently lost.
    if (!s.text) { parents.push(s.heading); return; }
    out.push({ heading: [...parents, s.heading].filter(Boolean).join(' — '), text: s.text });
    parents = [];
  });
  if (parents.length) out.push({ heading: parents[0], text: parents.slice(1).join('\n') });
  return out.filter(s => (s.heading + s.text).replace(/\s/g, '').length > 8);
}

// ---------- sizing ----------
function splitOversized(text) {
  if (text.length <= MAX_CHARS) return [text];
  // prefer breaking between list items, never mid-sentence
  const parts = text.split(/\n(?=\s*(?:[-*+]\s|\d+[)._-]\s|[أ-ي][)-]\s))/g)
    .map(p => p.trim()).filter(Boolean);
  if (parts.length <= 1) {
    const out = [];
    for (let i = 0; i < text.length; i += MAX_CHARS) out.push(text.slice(i, i + MAX_CHARS));
    return out;
  }
  const grouped = []; let buf = '';
  for (const p of parts) {
    if (buf && (buf + '\n' + p).length > MAX_CHARS) { grouped.push(buf.trim()); buf = p; }
    else buf = buf ? buf + '\n' + p : p;
  }
  if (buf) grouped.push(buf.trim());
  return grouped;
}

function mergeTiny(secs) {
  const out = [];
  for (const s of secs) {
    const prev = out[out.length - 1];
    if (prev && (s.text.length < MIN_CHARS || prev.text.length < MIN_CHARS)) {
      prev.text = `${prev.text}\n\n${s.heading ? s.heading + '\n' : ''}${s.text}`.trim();
    } else out.push({ ...s });
  }
  return out;
}

// ---------- main ----------
const input = $input.all()[0].json;
const cleaned = normalise(input.markdown || input.text || '');

const records = [];
splitIntoLessons(cleaned).forEach((lesson, li) => {
  mergeTiny(splitIntoSections(lesson.body)).forEach(sec => {
    splitOversized(sec.text).forEach(part => {
      // every chunk carries its lesson AND its section, so a fragment split off
      // by a page break can never lose track of which lesson it belongs to
      const header = [lesson.lesson, sec.heading].filter(Boolean).join(' — ');
      records.push({
        lesson_index: li,
        lesson: lesson.lesson,
        heading: sec.heading,
        text: header ? `${header}\n\n${part}` : part,
      });
    });
  });
});

// Original / currently-deployed shape — flat fields, matching what's
// actually running in n8n right now. Known limitation (documented in
// history_test_log.md): the Default Data Loader doesn't reliably recognise
// `text` as the content field, so retrieval quality for this collection is
// not fully trustworthy — parked for now per the decision to stop chasing
// the ingestion pipeline and focus on prompt-level fixes (v1.2) instead.
return records
  .filter(r => r.text.replace(/\s/g, '').length > 12)
  .map((r, i) => ({
    json: {
      chunk_id: `${SUBJECT.replace(/\s+/g, '_')}-${r.lesson_index}-${i}`,
      subject: SUBJECT,
      lesson: r.lesson,
      heading: r.heading,
      chunk_type: 'prose_block',
      text: r.text,
      char_count: r.text.length,
    },
  }));
